PREFIX='passage.catholic-church.missale-romanum.2010-english-icel-antiphonary.seasonal-'
class ReviewedSeasonalEnglishBodyTests(unittest.TestCase):
 @classmethod
 def setUpClass(cls):
  cls.root=ROOT/'src/sources/calendars';cls.records,problems=M._source_library_records(cls.root);assert not problems,problems
  ledger=tomllib.loads((ROOT/'src/sources/inventories/postconciliar-proper-translations-v1.toml').read_text())
  cls.rows=[r for r in ledger['untranslated'] if r.get('witness_passage_id','').startswith(PREFIX)]
  cls.structure=M.calendar_structure(cls.root,'postconciliar',M.book_tokens());cls.masses={m['key']:m for m in cls.structure['masses']}
 def test_exact_reviewed_targets_retained_bytes_and_wrong_occurrence_refusals(self):
  identity=lambda r:tuple(r[k] for k in ('mass','form_id','proper','cycle','occurrence','lang','extent'))
  self.assertEqual({identity(r) for r in self.rows},EXPECTED);self.assertEqual(len(self.rows),len(EXPECTED))
  for r in self.rows:
   self.assertEqual(M.scripture_body_absence_problems(r,'postconciliar',self.records),[])
   self.assertEqual(r['lang'],'en');self.assertEqual(r['extent'],'body');self.assertEqual(r['reason']['kind'],'rights-withheld')
   wrong=copy.deepcopy(r);wrong['occurrence']=99;self.assertTrue(M.scripture_body_absence_problems(wrong,'postconciliar',self.records))
  for rel,digest in RETAINED_FILES.items():
   self.assertEqual(hashlib.sha256((ROOT/rel).read_bytes()).hexdigest(),digest)
 def test_only_english_body_scope_preserves_latin_bible_components(self):
  units=[]
  for r in self.rows:
   p=[p for p in self.masses[r['mass']]['propers'] if p['name']==r['proper']][r['occurrence']-1]
   self.assertEqual(p['source'],'scripture');self.assertFalse(p.get('text'));self.assertFalse(p.get('translations'))
   u=p['coverage'];self.assertEqual(u['body_languages'],['en']);self.assertEqual(u['component'],'proper-body');self.assertIn('scripture_component',u)
   langs={x['lang']:x for x in u['languages']};self.assertEqual(langs['en']['availability'],'not-publishable');self.assertEqual(langs['la']['relationship'],'bible-reconstruction');units.append(u)
  summary=V.summarize(units,'selection');V.validate_summary(summary);langs={x['lang']:x for x in summary['languages']}
  self.assertEqual(langs['en']['targets'],len(EXPECTED));self.assertEqual(langs['la']['targets'],0)
 def test_withdrawn_vocative_rev19_and_unproved_heart_second_option_stay_out(self):
  self.assertFalse(any(r['mass']=='lent-5-wednesday' and r['proper']=='Entrance Antiphon' for r in self.rows))
  self.assertFalse(any(r['mass'] in {'easter-2-tuesday','easter-4-tuesday','easter-6-tuesday'} and r['proper']=='Entrance Antiphon' for r in self.rows))
  self.assertFalse(any(r['mass']=='most-sacred-heart-jesus' and r['proper']=='Communion Antiphon' and r['occurrence']==2 for r in self.rows))
  for mass,role,occ in [('lent-5-wednesday','Entrance Antiphon',1),('most-sacred-heart-jesus','Communion Antiphon',2)]:
   p=[p for p in self.masses[mass]['propers'] if p['name']==role][occ-1]
   self.assertNotEqual(p.get('coverage',{}).get('component'),'proper-body')
if __name__=='__main__':unittest.main()
